cd /private/tmp/claude-501/pr86-ci-live/lt/runs/sysspec99/fx; python3 -I - <<'E'
import json
d=json.load(open('system-spec/spec-state.json'))
cat=json.load(open('plugins/system-spec-harness/skills/run-system-spec-elicit/references/required-info-catalog.json'))
qa={q['id']:q for q in d['qa_log']}
cov={}
for q in d['qa_log']:
  for i in q.get('required_info_items') or []: cov.setdefault(i,[]).append(q['id'])
for it in cat['items']:
  print(it['item_id'],it['domain'],it['missing_effect'],it['evidence_required'],cov.get(it['item_id']))
m=d['matrix']
for k,r in m.items():
  c=r['web']
  for x in [c['qa_ref']]+c.get('qa_refs',[]):
    if x not in qa: print('DANGLING',k,x)
print({k:qa[k] for k in ['qa-009']}['qa-009'].get('superseded_by'),qa['qa-009'].get('superseded_note'),qa['qa-009'].get('superseded_at'))
print(json.dumps(qa['qa-001'].get('corrections'),ensure_ascii=False))
print(json.dumps(qa['qa-031'].get('design_applications'),ensure_ascii=False)[:500])
# who superseded
for q in d['qa_log']:
  if 'superseded_by' in q: print(q['id'],q['superseded_by'])
print(d['targets'] if len(json.dumps(d['targets']))<800 else 'targets long')
E

